// Top-down Heap Sort implementation (insertion-based)
function heapSortTopDown(arr) {
  const n = arr.length;

  // Build heap by inserting elements one by one (sift-up)
  for (let i = 1; i < n; i++) {
    let idx = i;

    // Sift-up: compare with parent and swap if needed
    while (idx > 0) {
      const parentIdx = Math.floor((idx - 1) / 2);

      if (arr[idx] > arr[parentIdx]) {
        [arr[idx], arr[parentIdx]] = [arr[parentIdx], arr[idx]];
        idx = parentIdx;
      } else {
        break;
      }
    }
  }

  // Extraction phase (same as standard heap sort)
  for (let i = n - 1; i > 0; i--) {
    [arr[0], arr[i]] = [arr[i], arr[0]];
    // Heapify the reduced heap (sift-down from root)
    let idx = 0;
    const newHeapSize = i;

    while (true) {
      let largest = idx;
      let left = 2 * idx + 1;
      let right = 2 * idx + 2;

      if (left < newHeapSize && arr[left] > arr[largest]) {
        largest = left;
      }

      if (right < newHeapSize && arr[right] > arr[largest]) {
        largest = right;
      }

      if (largest !== idx) {
        [arr[idx], arr[largest]] = [arr[largest], arr[idx]];
        idx = largest;
      } else {
        break;
      }
    }
  }

  return arr;
}

// Example usage
const arr = [5, 3, 8, 1, 7];
console.log('Original:', arr);
heapSortTopDown(arr);
console.log('Sorted:', arr); 
// [1, 3, 5, 7, 8]
